import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.preprocessing import StandardScaler
from sklearn.model_selection import StratifiedKFold
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Check if any feature shows significant association with outcome
    p_values = []
    feature_ids = feats.ids
    X = feats.x
    y = feats.y

    # Calculate p-values using Welch's t-test for each feature
    for i, fid in enumerate(feature_ids):
        group0 = X[y == 0, i]
        group1 = X[y == 1, i]
        if len(group0) > 1 and len(group1) > 1:
            t_stat, p_val = stats.ttest_ind(group0, group1, equal_var=False)
            p_values.append((fid, p_val))
        else:
            p_values.append((fid, 1.0))

    # Sort by p-value
    p_values.sort(key=lambda x: x[1])

    # Identify features with p < 0.05
    significant_features = [fid for fid, p in p_values if p < 0.05]

    # If no features are significant, return empty design
    if not significant_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Use all significant features for further analysis
    selected_features = significant_features[:MAX_DRIVERS]

    # Try to find a mechanism by checking strata consistency
    strata = feats.stratum
    unique_strata = list(set(strata))

    # Check if there's a consistent effect across strata
    strata_effects = {}
    for s in unique_strata:
        mask = [i for i in range(len(strata)) if strata[i] == s]
        if len(mask) == 0:
            continue
        strata_x = X[mask]
        strata_y = y[mask]

        # Calculate effect sizes for each feature in this stratum
        effects = []
        for i, fid in enumerate(feature_ids):
            if fid in selected_features:
                if i >= strata_x.shape[1]:  # Safety check
                    effects.append((fid, 0.0))
                    continue
                group0 = strata_x[strata_y == 0, i]
                group1 = strata_x[strata_y == 1, i]
                if len(group0) > 1 and len(group1) > 1:
                    t_stat, _ = stats.ttest_ind(group0, group1, equal_var=False)
                    effects.append((fid, t_stat))
                else:
                    effects.append((fid, 0.0))
        strata_effects[s] = effects

    # Check if effects are consistent across strata
    consistent_drivers = []
    for fid in selected_features:
        effects = []
        for s in unique_strata:
            if s not in strata_effects:
                continue
            # Find the effect for this feature in this stratum
            for f, effect in strata_effects[s]:
                if f == fid:
                    effects.append(effect)
                    break
            else:
                effects.append(0.0)

        # If we have effects and they're all consistently signed
        if effects and len([e for e in effects if e != 0]) > 0:
            signs = [1 if e > 0 else -1 if e < 0 else 0 for e in effects]
            if all(s == signs[0] for s in signs if s != 0):
                consistent_drivers.append(fid)

    # If no consistent drivers, return empty design
    if not consistent_drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Return design with consistent drivers
    return Design(
        drivers=tuple(consistent_drivers),
        columns=tuple(selected_features),
        products=(),
        loadings={}
    )

